const quizQuestions = [
  { q: 'What is the basic structural and functional unit of all living organisms?', ar: 'ما الوحدة التركيبية والوظيفية الأساسية لجميع الكائنات الحية؟', options: ['The organ', 'The cell', 'The tissue', 'The molecule'], optionsAr: ['العضو', 'الخلية', 'النسيج', 'الجزيء'], answer: 1, why: 'The cell is the smallest unit capable of carrying out all life processes.', whyAr: 'الخلية هي أصغر وحدة قادرة على القيام بجميع العمليات الحيوية.' },
  { q: 'Which organelle is known as the powerhouse of the cell?', ar: 'أي عضية تُعرف بأنها مصدر الطاقة في الخلية؟', options: ['Nucleus', 'Ribosome', 'Mitochondrion', 'Golgi body'], optionsAr: ['النواة', 'الريبوسوم', 'الميتوكوندريا', 'جهاز جولجي'], answer: 2, why: 'Mitochondria release energy from food through cellular respiration.', whyAr: 'تُطلق الميتوكوندريا الطاقة من الغذاء خلال التنفس الخلوي.' },
  { q: 'What surrounds the cell and controls what enters or leaves it?', ar: 'ما الذي يحيط بالخلية وينظم دخول المواد وخروجها؟', options: ['Cell membrane', 'Cytoplasm', 'Cell wall', 'Nucleus'], optionsAr: ['الغشاء الخلوي', 'السيتوبلازم', 'الجدار الخلوي', 'النواة'], answer: 0, why: 'The cell membrane is selectively permeable, regulating movement in and out.', whyAr: 'الغشاء الخلوي ذو نفاذية اختيارية، وينظم انتقال المواد من الخلية وإليها.' },
  { q: 'Where is most of a cell’s genetic material stored?', ar: 'أين تُخزَّن معظم المادة الوراثية للخلية؟', options: ['Vacuole', 'Nucleus', 'Cell membrane', 'Cytoplasm'], optionsAr: ['الفجوة', 'النواة', 'الغشاء الخلوي', 'السيتوبلازم'], answer: 1, why: 'The nucleus contains chromosomes, which are made of DNA.', whyAr: 'تحتوي النواة على الكروموسومات المكوّنة من الحمض النووي DNA.' },
  { q: 'Which structure is present in plant cells but not animal cells?', ar: 'أي تركيب يوجد في الخلايا النباتية ولا يوجد في الخلايا الحيوانية؟', options: ['Cell membrane', 'Cytoplasm', 'Cell wall', 'Mitochondrion'], optionsAr: ['الغشاء الخلوي', 'السيتوبلازم', 'الجدار الخلوي', 'الميتوكوندريا'], answer: 2, why: 'Plant cells have a rigid cell wall that provides support and protection.', whyAr: 'للخلايا النباتية جدار خلوي صلب يوفر الدعم والحماية.' },
  { q: 'What is the jelly-like material that fills the cell?', ar: 'ما المادة الشبيهة بالهلام التي تملأ الخلية؟', options: ['Cytoplasm', 'Chlorophyll', 'DNA', 'Cell wall'], optionsAr: ['السيتوبلازم', 'الكلوروفيل', 'الحمض النووي', 'الجدار الخلوي'], answer: 0, why: 'The cytoplasm fills the cell and is where many chemical reactions take place.', whyAr: 'يملأ السيتوبلازم الخلية وتحدث فيه العديد من التفاعلات الكيميائية.' },
  { q: 'What is the main role of chloroplasts?', ar: 'ما الوظيفة الأساسية للبلاستيدات الخضراء؟', options: ['Store water', 'Make proteins', 'Carry out photosynthesis', 'Release energy'], optionsAr: ['تخزين الماء', 'صنع البروتينات', 'إتمام البناء الضوئي', 'إطلاق الطاقة'], answer: 2, why: 'Chloroplasts contain chlorophyll, which captures light for photosynthesis.', whyAr: 'تحتوي البلاستيدات على الكلوروفيل الذي يمتص الضوء لعملية البناء الضوئي.' },
  { q: 'Which tool is commonly used to observe cells?', ar: 'ما الأداة الشائعة لمشاهدة الخلايا؟', options: ['Telescope', 'Microscope', 'Periscope', 'Thermometer'], optionsAr: ['التلسكوب', 'المجهر', 'البيرسكوب', 'مقياس الحرارة'], answer: 1, why: 'A microscope magnifies objects too small to see clearly with the naked eye.', whyAr: 'يكبّر المجهر الأجسام التي لا يمكن رؤيتها بوضوح بالعين المجردة.' },
  { q: 'What do ribosomes help a cell produce?', ar: 'ما الذي تساعد الريبوسومات الخلية على إنتاجه؟', options: ['Proteins', 'Water', 'Light', 'Oxygen'], optionsAr: ['البروتينات', 'الماء', 'الضوء', 'الأكسجين'], answer: 0, why: 'Ribosomes are the sites where proteins are assembled.', whyAr: 'الريبوسومات هي المواقع التي تُصنَّع فيها البروتينات.' },
  { q: 'A group of similar cells working together forms a…', ar: 'مجموعة من الخلايا المتشابهة التي تعمل معًا تكوّن…', options: ['System', 'Tissue', 'Organism', 'Molecule'], optionsAr: ['جهازًا', 'نسيجًا', 'كائنًا حيًا', 'جزيئًا'], answer: 1, why: 'Similar cells combine to form tissues, which then build organs.', whyAr: 'تتحد الخلايا المتشابهة لتكوّن أنسجة، ثم تكوّن الأنسجة الأعضاء.' },
]

