function App() {
  const [lang, setLang] = useState<Lang>(() => (localStorage.getItem('athar-lang') as Lang) || 'ar')
  const t = text[lang]
  const [role, setRole] = useState<Role>(() => (localStorage.getItem('athar-role') as Role) || 'student')
  const [view, setView] = useState<View>(() => localStorage.getItem('athar-view') === 'overview' ? 'overview' : 'welcome')
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login')
  const [onboarding, setOnboarding] = useState<'system' | 'grade' | 'payment' | 'success' | null>(null)
  const [system, setSystem] = useState(() => localStorage.getItem('athar-system') ?? 'Arabic schools')
  const [grade, setGrade] = useState(() => localStorage.getItem('athar-grade') ?? 'Grade 11')
  const [query, setQuery] = useState('')
  const [searchOpen, setSearchOpen] = useState(false)
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const [unread, setUnread] = useState(3)
  const [selectedSubject, setSelectedSubject] = useState('biology')
  const [selectedQuestion, setSelectedQuestion] = useState(0)
  const [answers, setAnswers] = useState<number[]>(Array(10).fill(-1))
  const [seconds, setSeconds] = useState(600)
  const [submitted, setSubmitted] = useState(false)
  const [page, setPage] = useState(1)
  const [toast, setToast] = useState('')
  const [menuOpen, setMenuOpen] = useState(false)
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [studentName, setStudentName] = useState('Mariam Ahmed')
  const [saved, setSaved] = useState(() => localStorage.getItem('athar-summary-saved') === 'true')
  const [visited, setVisited] = useState(() => Number(localStorage.getItem('athar-chapters-visited')) || 8)
  const [completedQuizzes, setCompletedQuizzes] = useState(() => Number(localStorage.getItem('athar-quizzes-completed')) || 6)

  const isRtl = lang === 'ar'
  const subject = subjects.find((item) => item.id === selectedSubject) ?? subjects[0]
  const score = quizQuestions.reduce((total, item, i) => total + (answers[i] === item.answer ? 1 : 0), 0)
  const filteredResults = useMemo(() => {
    if (!query.trim()) return []
    const needle = query.toLowerCase()
    return subjects.flatMap((item) => {
      const localSubject = item.name[lang].toLowerCase()
      const chapters = item.lessons.filter((lesson) => lesson.toLowerCase().includes(needle) || lesson.toLowerCase().includes(query))
      return (localSubject.includes(needle) || item.name.ar.includes(query) ? [{ title: item.name[lang], kind: lang === 'ar' ? 'مادة دراسية' : 'Subject', subjectId: item.id }] : [])
        .concat(chapters.map((chapter) => ({ title: chapter, kind: lang === 'ar' ? 'فصل دراسي' : 'Chapter', subjectId: item.id })))
    })
  }, [lang, query])

  useEffect(() => { localStorage.setItem('athar-lang', lang); document.documentElement.lang = lang; document.documentElement.dir = isRtl ? 'rtl' : 'ltr' }, [isRtl, lang])
  useEffect(() => { localStorage.setItem('athar-role', role) }, [role])
  useEffect(() => { localStorage.setItem('athar-system', system) }, [system])
  useEffect(() => { localStorage.setItem('athar-grade', grade) }, [grade])
  useEffect(() => { localStorage.setItem('athar-summary-saved', String(saved)) }, [saved])
  useEffect(() => { localStorage.setItem('athar-chapters-visited', String(visited)) }, [visited])
  useEffect(() => { localStorage.setItem('athar-quizzes-completed', String(completedQuizzes)) }, [completedQuizzes])
  useEffect(() => {
    if (view === 'results') {
      localStorage.setItem('athar-last-quiz-result', JSON.stringify({ score, answers, completedAt: new Date().toISOString() }))
    }
  }, [answers, score, view])
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 2600); return () => window.clearTimeout(timer) }, [toast])
  useEffect(() => {
    if (view !== 'quiz' || submitted) return
    const timer = window.setInterval(() => setSeconds((value) => {
      if (value <= 1) { window.clearInterval(timer); setSubmitted(true); setView('results'); return 0 }
      return value - 1
    }), 1000)
    return () => window.clearInterval(timer)
  }, [view, submitted])
  useEffect(() => {
    const warn = (event: KeyboardEvent) => {
      if ((event.key === 'PrintScreen' || (event.ctrlKey && event.key.toLowerCase() === 'p')) && view === 'summary') {
        setToast(lang === 'ar' ? 'يرجى الحفاظ على خصوصية المحتوى التعليمي.' : 'Please respect the privacy of this learning content.')
      }
    }
    const menu = (event: MouseEvent) => { if (view === 'summary') { event.preventDefault(); setToast(lang === 'ar' ? 'المحتوى التعليمي مخصص للاستخدام الشخصي.' : 'Learning content is for personal use.') } }
    document.addEventListener('keydown', warn); document.addEventListener('contextmenu', menu)
    return () => { document.removeEventListener('keydown', warn); document.removeEventListener('contextmenu', menu) }
  }, [lang, view])

  function go(viewName: View) { setView(viewName); setSearchOpen(false); setMenuOpen(false) }
  function demoLogin(nextRole: Role) {
    setRole(nextRole)
    if (nextRole === 'parent') setStudentName('Mariam Ahmed')
    else if (!studentName.trim()) setStudentName(lang === 'ar' ? 'مريم أحمد' : 'Mariam Ahmed')
    localStorage.setItem('athar-view', 'overview'); setView('overview')
  }
  function startQuiz() { setAnswers(Array(10).fill(-1)); setSelectedQuestion(0); setSeconds(600); setSubmitted(false); go('quiz') }
  function submitQuiz() {
    if (answers.includes(-1)) { setToast(t.selectAnswer); return }
    setSubmitted(true); setCompletedQuizzes((count) => count + 1); go('results')
  }
  function finishPayment() { setOnboarding('success'); setToast(lang === 'ar' ? 'تم تفعيل اشتراكك بنجاح' : 'Your subscription is now active') }
  function signOut() { setView('welcome'); setOnboarding(null); localStorage.removeItem('athar-view') }
  function formatTime(value: number) { return `${Math.floor(value / 60).toString().padStart(2, '0')}:${(value % 60).toString().padStart(2, '0')}` }

  const sidebarLinks = role === 'admin'
    ? [{ id: 'overview' as View, icon: LayoutDashboard, label: t.overview }, { id: 'content' as View, icon: BookOpen, label: t.content }, { id: 'users' as View, icon: Users, label: t.users }, { id: 'payments' as View, icon: WalletCards, label: t.payments }, { id: 'progress' as View, icon: BarChart3, label: t.progress }]
    : role === 'parent'
      ? [{ id: 'overview' as View, icon: LayoutDashboard, label: t.overview }, { id: 'progress' as View, icon: BarChart3, label: t.childProgress }, { id: 'achievements' as View, icon: Trophy, label: t.achievements }, { id: 'payments' as View, icon: WalletCards, label: t.payments }]
      : [{ id: 'overview' as View, icon: LayoutDashboard, label: t.overview }, { id: 'subjects' as View, icon: BookOpen, label: t.subjects }, { id: 'tasks' as View, icon: Target, label: t.tasks }, { id: 'achievements' as View, icon: Trophy, label: t.achievements }, { id: 'payments' as View, icon: WalletCards, label: t.payments }]

  if (view === 'welcome') return <main className="welcome-page" dir={isRtl ? 'rtl' : 'ltr'}>
    <div className="welcome-top"><Brand /><button className="lang-button" onClick={() => setLang(isRtl ? 'en' : 'ar')}><Languages size={17} />{isRtl ? 'English' : 'العربية'}</button></div>
    <div className="welcome-layout">
      <section className="welcome-hero">
        <div className="hero-glow" />
        <div className="eyebrow"><Sparkles size={14} /> {lang === 'ar' ? 'تعلّم أذكى، أثر أكبر' : 'A brighter way to learn'}</div>
        <h1>{t.welcome}<br /><span>{lang === 'ar' ? 'أَثَر' : 'ATHAR'}</span></h1>
        <p>{t.loginSub}</p>
        <div className="hero-quote"><span className="quote-mark">“</span><div><strong>{lang === 'ar' ? 'كل معرفة تترك أثرًا.' : 'Every lesson leaves a mark.'}</strong><small>{lang === 'ar' ? 'رحلتك تبدأ هنا، وتصل بك إلى أبعد مما تتخيّل.' : 'Your journey starts here, and goes further than you imagine.'}</small></div></div>
        <div className="welcome-illustration">
          <div className="orbit orbit-one" /><div className="orbit orbit-two" />
          <div className="book-art"><BookOpen size={58} strokeWidth={1.3} /></div>
          <div className="float-card float-card-one"><span className="float-icon"><Trophy size={17} /></span><span><b>+240 XP</b><small>{lang === 'ar' ? 'أثر جديد!' : 'New milestone!'}</small></span></div>
          <div className="float-card float-card-two"><span className="float-icon lilac-icon"><Zap size={17} /></span><span><b>7 {lang === 'ar' ? 'أيام' : 'days'}</b><small>{lang === 'ar' ? 'سلسلة تعلّم' : 'learning streak'}</small></span></div>
        </div>
      </section>
      <section className="auth-card">
        <div className="auth-heading"><span className="auth-spark"><Sparkles size={17} /></span><h2>{authMode === 'login' ? t.login : t.register}</h2><p>{authMode === 'login' ? t.loginSub : t.getStarted}</p></div>
        <div className="auth-tabs"><button className={authMode === 'login' ? 'active' : ''} onClick={() => setAuthMode('login')}>{t.login}</button><button className={authMode === 'register' ? 'active' : ''} onClick={() => setAuthMode('register')}>{t.register}</button></div>
        {authMode === 'register' && <label className="field-label">{t.name}<div className="input-wrap"><UserRound size={17} /><input value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder={t.name} /></div></label>}
        <label className="field-label">{t.email}<div className="input-wrap"><MessageCircle size={17} /><input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="name@example.com" /></div></label>
        <label className="field-label">{t.password}<div className="input-wrap"><LockKeyhole size={17} /><input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" /></div></label>
        <button className="primary-button full-button" onClick={() => { if (!email || !password) { setToast(lang === 'ar' ? 'أدخلي البريد الإلكتروني وكلمة المرور للمتابعة' : 'Enter your email and password to continue'); return } if (authMode === 'register') setOnboarding('system'); else demoLogin('student') }}>{authMode === 'login' ? t.login : t.getStarted}<ArrowLeft size={17} className={isRtl ? '' : 'flip-icon'} /></button>
        <div className="divider"><span>{lang === 'ar' ? 'أو جرّبي المنصة' : 'or explore ATHAR'}</span></div>
        <div className="demo-options"><button onClick={() => demoLogin('student')}><span className="demo-avatar student-avatar"><GraduationCap size={17} /></span><span>{t.student}<small>{lang === 'ar' ? 'استكشفي تجربة الطالب' : 'Explore as a student'}</small></span><ChevronLeft size={17} /></button><button onClick={() => demoLogin('parent')}><span className="demo-avatar parent-avatar"><Users size={17} /></span><span>{t.parent}<small>{lang === 'ar' ? 'تابعي تقدّم طفلك' : 'Monitor your child’s progress'}</small></span><ChevronLeft size={17} /></button><button onClick={() => demoLogin('admin')}><span className="demo-avatar admin-avatar"><Settings size={17} /></span><span>{t.admin}<small>{lang === 'ar' ? 'إدارة المنصة والمحتوى' : 'Manage content and accounts'}</small></span><ChevronLeft size={17} /></button></div>
        <div className="secure-note"><ShieldCheck size={14} />{lang === 'ar' ? 'بياناتك آمنة ومحمية دائمًا' : 'Your data is always safe and secure'}</div>
      </section>
    </div>
    <div className="welcome-footer"><span>© 2025 ATHAR · {t.subtitleEnglish}</span><span>{lang === 'ar' ? 'صُنع بشغف في مصر' : 'Made with care in Egypt'} <span className="heart">♥</span></span></div>
    <Onboarding active={onboarding} setActive={setOnboarding} lang={lang} t={t} system={system} setSystem={setSystem} grade={grade} setGrade={setGrade} finishPayment={finishPayment} onDone={() => { setOnboarding(null); demoLogin('student') }} />
    <Toast message={toast} />
  </main>

  const fullName = role === 'parent' ? (lang === 'ar' ? 'أحمد محمد' : 'Ahmed Mohamed') : role === 'admin' ? (lang === 'ar' ? 'فريق أثَر' : 'ATHAR team') : t.nameStudent

  return <div className={`app-shell ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
    <aside className={`sidebar ${menuOpen ? 'sidebar-open' : ''}`}>
      <div className="sidebar-brand"><Brand /></div>
      <div className="workspace-label">{lang === 'ar' ? 'مساحة التعلّم' : 'LEARNING SPACE'}</div>
      <nav className="side-nav">
        {sidebarLinks.map((item) => <button key={item.id} className={`nav-item ${view === item.id ? 'selected' : ''}`} onClick={() => go(item.id)}><item.icon size={19} /><span>{item.label}</span>{item.id === 'tasks' && <i className="nav-count">2</i>}</button>)}
      </nav>
      {role === 'student' && <div className="sidebar-goal"><div className="goal-head"><span>{t.dailyGoal}</span><span>75%</span></div><div className="goal-track"><span style={{ width: '75%' }} /></div><p>{lang === 'ar' ? '45 دقيقة' : '45 minutes'} <small>{t.goalDone}</small></p><div className="mini-streak"><span>✦</span><b>7</b><small>{t.streak}</small></div></div>}
      <div className="sidebar-spacer" />
      <button className="side-help" onClick={() => setToast(lang === 'ar' ? 'فريق أثَر هنا لمساعدتك — support@athar.app' : 'ATHAR support is here — support@athar.app')}><span className="help-mark"><CircleHelp size={18} /></span><span><b>{lang === 'ar' ? 'تحتاجين مساعدة؟' : 'Need a hand?'}</b><small>{lang === 'ar' ? 'نحن هنا لمساعدتك' : 'We’re here to help'}</small></span><ArrowUpRight size={15} /></button>
      <div className="sidebar-user"><span className="profile-avatar">{role === 'admin' ? 'A' : role === 'parent' ? 'أ' : 'م'}</span><span className="user-copy"><b>{fullName}</b><small>{role === 'admin' ? t.admin : role === 'parent' ? t.parent : t.grade}</small></span><button aria-label={t.signOut} onClick={signOut}><LogOut size={17} /></button></div>
    </aside>
    {menuOpen && <button className="mobile-backdrop" onClick={() => setMenuOpen(false)} aria-label="Close menu" />}
    <main className="main-panel">
      <header className="topbar">
        <button className="mobile-menu" onClick={() => setMenuOpen(!menuOpen)} aria-label="Toggle navigation"><Menu size={21} /></button>
        <div className="breadcrumb"><span>{role === 'parent' ? t.parentDash : role === 'admin' ? t.adminDash : t.home}</span><ChevronLeft size={14} /><b>{view === 'overview' ? t.overview : sidebarLinks.find((link) => link.id === view)?.label ?? (view === 'summary' || view === 'quiz' || view === 'results' ? subject.name[lang] : t.subjects)}</b></div>
        <div className="topbar-actions">
          <div className={`search-box ${searchOpen ? 'search-active' : ''}`}><Search size={17} /><input aria-label={t.search} placeholder={t.search} value={query} onFocus={() => setSearchOpen(true)} onChange={(e) => setQuery(e.target.value)} /><kbd>⌘ K</kbd>{searchOpen && query && <button className="clear-search" onClick={() => setQuery('')} aria-label="Clear search"><X size={14} /></button>}</div>
          <button className="icon-button language-toggle" onClick={() => setLang(isRtl ? 'en' : 'ar')} aria-label="Change language"><Languages size={18} /><span>{isRtl ? 'EN' : 'عربي'}</span></button>
          <div className="notification-wrap"><button className="icon-button notification-button" aria-label={t.notifications} onClick={() => { setNotificationsOpen(!notificationsOpen); if (notificationsOpen) setUnread(0) }}><Bell size={19} />{unread > 0 && <i className="notification-dot">{unread}</i>}</button>
            <AnimatePresence>{notificationsOpen && <motion.div className="notification-popover" initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 8 }}><div className="popover-head"><b>{t.notifications}</b><button onClick={() => setUnread(0)}>{lang === 'ar' ? 'تحديد كمقروءة' : 'Mark all read'}</button></div><Notice icon={<BookOpen size={16} />} title={lang === 'ar' ? 'فصل جديد في الأحياء' : 'A new Biology chapter'} body={lang === 'ar' ? 'الخلية: التركيب والوظيفة' : 'The cell: structure & function'} time={lang === 'ar' ? 'منذ ساعتين' : '2 hours ago'} /><Notice icon={<Target size={16} />} title={lang === 'ar' ? 'اختبار جديد بانتظارك' : 'A new quiz is ready'} body={lang === 'ar' ? 'اختبار الفصل الأول · ١٠ أسئلة' : 'Chapter 1 quiz · 10 questions'} time={lang === 'ar' ? 'أمس' : 'Yesterday'} /><Notice icon={<Award size={16} />} title={lang === 'ar' ? 'إنجاز رائع!' : 'Great achievement!'} body={lang === 'ar' ? 'أكملتِ ٧ أيام من التعلّم المتواصل' : 'You hit a 7-day learning streak'} time={lang === 'ar' ? 'منذ يومين' : '2 days ago'} /></motion.div>}</AnimatePresence>
          </div>
          <button className="top-avatar" onClick={signOut} title={t.signOut}>{role === 'admin' ? 'A' : role === 'parent' ? 'أ' : 'م'}</button>
        </div>
        {searchOpen && query && <div className="search-results">{filteredResults.length ? filteredResults.map((item, index) => <button key={`${item.subjectId}-${item.title}-${index}`} onClick={() => { setSelectedSubject(item.subjectId); go('summary') }}><span className="result-icon"><Search size={15} /></span><span className="result-title">{item.title}<small>{subjects.find((s) => s.id === item.subjectId)?.name[lang]} · {item.kind}</small></span><ArrowUpRight size={15} /></button>) : <div className="no-results">{t.noResults}</div>}</div>}
      </header>
      <div className="page-content" onClick={() => { if (searchOpen) setSearchOpen(false) }}>
        <AnimatePresence mode="wait">
          <motion.div key={view} className="page-transition" initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -5 }} transition={{ duration: .22 }}>
            {view === 'overview' && <Overview t={t} lang={lang} role={role} subjects={subjects} onNavigate={go} onSubject={(id) => { setSelectedSubject(id); go('summary'); setPage(1); setVisited((v) => v + 1) }} />}
            {view === 'subjects' && <SubjectsPage t={t} lang={lang} onSubject={(id) => { setSelectedSubject(id); go('summary'); setPage(1); setVisited((v) => v + 1) }} />}
            {view === 'achievements' && <Achievements t={t} lang={lang} completedQuizzes={completedQuizzes} visited={visited} onSubject={(id) => { setSelectedSubject(id); go('summary') }} />}
            {view === 'tasks' && <Tasks lang={lang} onStart={startQuiz} />}
            {view === 'summary' && <Summary t={{ ...t, chapterTitle: lang === 'ar' ? subject.nextAr : subject.next, summaryText: selectedSubject === 'biology' ? t.summaryText : lang === 'ar' ? `يقدّم هذا الفصل أفكار ${subject.name.ar} الأساسية، ويربط بين المفاهيم خطوةً بخطوة لتطبيقها بثقة.` : `This chapter introduces key ${subject.name.en} concepts and connects them step by step for confident application.` }} lang={lang} subject={subject} page={page} setPage={setPage} saved={saved} setSaved={setSaved} onBack={() => go('subjects')} onStartQuiz={startQuiz} />}
            {view === 'quiz' && <Quiz t={t} lang={lang} seconds={seconds} formatTime={formatTime} index={selectedQuestion} setIndex={setSelectedQuestion} answers={answers} setAnswers={setAnswers} onSubmit={submitQuiz} onBack={() => go('summary')} />}
            {view === 'results' && <Results t={t} lang={lang} answers={answers} score={score} onBack={() => go('subjects')} onRetry={startQuiz} />}
            {view === 'payments' && <Payments t={t} lang={lang} onUpgrade={() => setOnboarding('payment')} />}
            {view === 'progress' && <Progress t={t} lang={lang} role={role} />}
            {view === 'content' && <AdminContent t={t} lang={lang} onToast={setToast} />}
            {view === 'users' && <AdminUsers t={t} lang={lang} onToast={setToast} />}
          </motion.div>
        </AnimatePresence>
      </div>
      <footer className="app-footer"><span>© 2025 ATHAR · {t.subtitleEnglish}</span><span><ShieldCheck size={13} /> {lang === 'ar' ? 'تعلّمك في مساحة آمنة' : 'A safe space to learn'}</span></footer>
    </main>
    <Onboarding active={onboarding} setActive={setOnboarding} lang={lang} t={t} system={system} setSystem={setSystem} grade={grade} setGrade={setGrade} finishPayment={finishPayment} onDone={() => { setOnboarding(null); go('overview') }} />
    <Toast message={toast} />
  </div>
}

function Brand() { return <div className="brand-lockup"><span className="brand-symbol">أ</span><span className="brand-word">ATHAR<small>أَثَر</small></span></div> }

function Overview({ t, lang, role, subjects: list, onNavigate, onSubject }: { t: typeof text.ar; lang: Lang; role: Role; subjects: typeof subjects; onNavigate: (view: View) => void; onSubject: (id: string) => void }) {
  const [period, setPeriod] = useState('week')
  const isParent = role === 'parent'
  const isAdmin = role === 'admin'
  return <div className="overview-page">
    <div className="page-heading"><div><div className="eyebrow-small">{lang === 'ar' ? 'الخميس، ٢٠ نوفمبر ٢٠٢٦' : 'THURSDAY, NOVEMBER 20, 2026'} <span className="live-dot" /></div><h1>{isParent ? (lang === 'ar' ? 'صباح الخير، أحمد 👋' : 'Good morning, Ahmed 👋') : isAdmin ? (lang === 'ar' ? 'أهلًا بفريق أثَر 👋' : 'Welcome, ATHAR team 👋') : t.greeting}</h1><p>{isParent ? (lang === 'ar' ? 'مريم تحقق تقدمًا رائعًا هذا الأسبوع.' : 'Mariam is making wonderful progress this week.') : isAdmin ? (lang === 'ar' ? 'إليك نظرة سريعة على منصتك اليوم.' : 'Here’s what’s happening across your platform today.') : t.subtitle}</p></div><button className="date-filter"><span className="calendar-dot">◷</span>{t.thisWeek}<ChevronDown size={15} /></button></div>
    <div className="welcome-banner"><div className="banner-copy"><span className="banner-pill"><Sparkles size={13} />{lang === 'ar' ? 'مساحة مخصصة لك' : 'YOUR LEARNING SPACE'}</span><h2>{isParent ? (lang === 'ar' ? <>رحلة مريم، <em>بخطى واثقة.</em></> : <>Mariam’s journey, <em>in full bloom.</em></>) : isAdmin ? (lang === 'ar' ? <>أثَرٌ يبدأ بفريق، <em>ويصل للجميع.</em></> : <>Built with care, <em>growing every day.</em></>) : lang === 'ar' ? <>كل يوم تتعلّمين فيه، <em>تتركين أثَرًا.</em></> : <>Every day you learn, <em>you leave a mark.</em></>}</h2><p>{isParent ? (lang === 'ar' ? 'اطّلع على إنجازاتها وخطتها القادمة.' : 'See her milestones and upcoming plan.') : isAdmin ? (lang === 'ar' ? 'تابع تجربة الطلاب وأضف محتوى جديدًا.' : 'Track student experience and publish new content.') : (lang === 'ar' ? 'رحلتك التعليمية تسير بخطى رائعة. هيا نكمل معًا.' : 'You’re making wonderful progress. Let’s keep it going.')}</p><button className="banner-button" onClick={() => isAdmin ? onNavigate('content') : isParent ? onNavigate('progress') : onSubject('biology')}>{isAdmin ? (lang === 'ar' ? 'إدارة المحتوى' : 'Manage content') : isParent ? (lang === 'ar' ? 'عرض التقدم' : 'View progress') : t.continue}<ArrowLeft size={16} className={lang === 'en' ? 'flip-icon' : ''} /></button></div><div className="banner-art"><div className="banner-disc disc-back" /><div className="banner-disc disc-front" /><div className="banner-leaf leaf-a" /><div className="banner-leaf leaf-b" /><div className="banner-book"><BookOpen size={41} strokeWidth={1.4} /></div><span className="art-star star-a">✳</span><span className="art-star star-b">✦</span><span className="art-sparkle">✧</span></div></div>
    <div className="stats-row"><StatCard icon={<Target size={17} />} tone="stat-purple" value={isAdmin ? '1,284' : '68%'} label={isAdmin ? (lang === 'ar' ? 'إجمالي الطلاب' : 'Total students') : (lang === 'ar' ? 'تقدّمك الكلي' : 'Overall progress')} detail={isAdmin ? '+12%' : '+8.4%'} detailTone="positive" /><StatCard icon={<Zap size={17} />} tone="stat-peach" value={isAdmin ? '24' : '7'} label={isAdmin ? (lang === 'ar' ? 'محتوى جديد' : 'New content') : t.streak} detail={isAdmin ? (lang === 'ar' ? 'هذا الأسبوع' : 'this week') : (lang === 'ar' ? 'أنتِ تتألقين!' : 'You’re on fire!')} /><StatCard icon={<Clock3 size={17} />} tone="stat-blue" value={isAdmin ? '86%' : '12.5'} label={isAdmin ? (lang === 'ar' ? 'نسبة إكمال الاختبارات' : 'Quiz completion') : t.hours} detail={isAdmin ? '+4.2%' : (lang === 'ar' ? 'ساعة هذا الشهر' : 'hrs this month')} /><StatCard icon={<Award size={17} />} tone="stat-mint" value={isAdmin ? '8' : '23'} label={isAdmin ? (lang === 'ar' ? 'إنجازات تم فتحها' : 'Badges unlocked') : (lang === 'ar' ? 'إنجازًا' : 'Achievements')} detail={isAdmin ? (lang === 'ar' ? 'هذا الشهر' : 'this month') : (lang === 'ar' ? 'إنجاز رائع!' : 'Looking good!')} /></div>
    <div className="dashboard-grid">
      <section className="panel subjects-panel"><PanelHeading title={isParent ? (lang === 'ar' ? 'المواد الدراسية' : 'Subjects') : isAdmin ? (lang === 'ar' ? 'المحتوى الدراسي' : 'Learning content') : t.continue} action={t.viewAll} onAction={() => onNavigate(isAdmin ? 'content' : 'subjects')} /><div className="subject-list">{list.slice(0, 3).map((item) => <button key={item.id} className="subject-row" onClick={() => onSubject(item.id)}><span className={`subject-icon ${item.tone}`}><item.icon size={20} /></span><span className="subject-main"><b>{item.name[lang]}</b><small>{isParent ? (lang === 'ar' ? `${item.done} من ${item.chapters} فصول مكتملة` : `${item.done} of ${item.chapters} chapters completed`) : lang === 'ar' ? `${item.done} من ${item.chapters} فصول` : `${item.done} of ${item.chapters} chapters`}</small><span className="progress-track"><span style={{ width: `${item.progress}%` }} /></span></span><span className="subject-progress">{item.progress}%</span><ChevronLeft size={16} /></button>)}</div><button className="panel-bottom-link" onClick={() => onNavigate(isAdmin ? 'content' : 'subjects')}>{t.exploreAll}<ArrowLeft size={15} className={lang === 'en' ? 'flip-icon' : ''} /></button></section>
      <section className="panel progress-panel"><PanelHeading title={isParent ? (lang === 'ar' ? 'التقدّم الدراسي' : 'Learning progress') : t.yourProgress} action={t.viewProgress} onAction={() => onNavigate('achievements')} /><div className="chart-summary"><div><strong>{isAdmin ? '86%' : '72%'}</strong><small>{isAdmin ? (lang === 'ar' ? 'نشاط الطلاب' : 'student activity') : (lang === 'ar' ? 'متوسط التقدّم' : 'average progress')}</small></div><span className="chart-change">↗ 12.8%</span></div><WeeklyChart lang={lang} /><div className="chart-legend"><span><i className="legend-main" />{lang === 'ar' ? 'هذا الأسبوع' : 'This week'}</span><span><i className="legend-muted" />{lang === 'ar' ? 'الأسبوع الماضي' : 'Last week'}</span><div className="chart-period"><button className={period === 'week' ? 'period-on' : ''} onClick={() => setPeriod('week')}>{lang === 'ar' ? 'أسبوع' : 'Week'}</button><button className={period === 'month' ? 'period-on' : ''} onClick={() => setPeriod('month')}>{lang === 'ar' ? 'شهر' : 'Month'}</button></div></div></section>
      <section className="panel activity-panel"><PanelHeading title={t.recent} action={lang === 'ar' ? 'عرض الكل' : 'View all'} onAction={() => onNavigate('achievements')} subtitle={t.recentSub} /><div className="activity-list"><Activity icon={<CheckCircle2 size={17} />} tone="act-green" title={lang === 'ar' ? 'أنهيتِ فصل الخلية' : 'Finished The cell chapter'} time={lang === 'ar' ? 'اليوم، ٩:٤٠ ص' : 'Today, 9:40 AM'} /><Activity icon={<Target size={17} />} tone="act-purple" title={lang === 'ar' ? 'نتيجة اختبار مميزة!' : 'A brilliant quiz result!'} time={lang === 'ar' ? 'أمس، ٤:١٥ م' : 'Yesterday, 4:15 PM'} /><Activity icon={<BookOpen size={17} />} tone="act-blue" title={lang === 'ar' ? 'بدأتِ فصل المعادلات التربيعية' : 'Started Quadratic equations'} time={lang === 'ar' ? 'الأربعاء، ١١:٢٠ ص' : 'Wed, 11:20 AM'} /></div></section>
      <section className="panel week-panel"><PanelHeading title={t.upcoming} action={lang === 'ar' ? 'الخطة كاملة' : 'Full plan'} onAction={() => onNavigate('tasks')} subtitle={lang === 'ar' ? 'أنتِ على المسار الصحيح، استمرّي!' : 'You’re right on track. Keep going!'} /><div className="week-rows"><WeekRow day={lang === 'ar' ? 'اليوم' : 'TODAY'} title={lang === 'ar' ? 'اختبار: الخلية' : 'Quiz: The cell'} desc={lang === 'ar' ? 'الأحياء · ١٠ أسئلة' : 'Biology · 10 questions'} time="10:30" tone="blue" onClick={() => onSubject('biology')} /><WeekRow day={lang === 'ar' ? 'غدًا' : 'TOMORROW'} title={lang === 'ar' ? 'ملخص: المعادلات' : 'Summary: Equations'} desc={lang === 'ar' ? 'الرياضيات · ١٥ دقيقة' : 'Mathematics · 15 min'} time="11:00" tone="purple" onClick={() => onSubject('math')} /><WeekRow day={lang === 'ar' ? 'السبت' : 'SATURDAY'} title={lang === 'ar' ? 'جلسة مراجعة' : 'Revision session'} desc={lang === 'ar' ? 'الفيزياء · ٢٠ دقيقة' : 'Physics · 20 min'} time="09:00" tone="peach" onClick={() => onSubject('physics')} /></div></section>
    </div>
    <div className="trust-strip"><span><ShieldCheck size={15} />{lang === 'ar' ? 'تعلّم آمن ومخصص لك' : 'A safe, personal learning space'}</span><span><Sparkles size={14} />{lang === 'ar' ? 'كل خطوة تُقرّبك من هدفك' : 'Every step takes you closer'}</span><button onClick={() => onNavigate('achievements')}>{lang === 'ar' ? 'اكتشفي إنجازاتك' : 'See your achievements'}<ArrowUpRight size={14} /></button></div>
  </div>
}

function StatCard({ icon, tone, value, label, detail, detailTone }: { icon: React.ReactNode; tone: string; value: string; label: string; detail: string; detailTone?: string }) { return <div className="stat-card"><span className={`stat-icon ${tone}`}>{icon}</span><div className="stat-value">{value}</div><div className="stat-label">{label}</div><div className={`stat-detail ${detailTone ?? ''}`}>{detail}</div><span className="stat-spark">✦</span></div> }
function PanelHeading({ title, action, onAction, subtitle }: { title: string; action?: string; onAction?: () => void; subtitle?: string }) { return <div className="panel-heading"><div><h3>{title}</h3>{subtitle && <p>{subtitle}</p>}</div>{action && <button onClick={onAction}>{action}<ArrowLeft size={14} /></button>}</div> }
function Activity({ icon, tone, title, time }: { icon: React.ReactNode; tone: string; title: string; time: string }) { return <div className="activity-row"><span className={`activity-icon ${tone}`}>{icon}</span><span className="activity-copy"><b>{title}</b><small>{time}</small></span><span className="activity-check"><Check size={14} /></span></div> }
function WeekRow({ day, title, desc, time, tone, onClick }: { day: string; title: string; desc: string; time: string; tone: string; onClick: () => void }) { return <button className="week-row" onClick={onClick}><span className={`week-marker ${tone}`} /><span className="week-copy"><small>{day}</small><b>{title}</b><span>{desc}</span></span><span className="week-time"><Clock3 size={12} />{time}</span></button> }
function WeeklyChart({ lang }: { lang: Lang }) { const days = lang === 'ar' ? ['ح', 'ن', 'ث', 'ر', 'خ', 'ج', 'س'] : ['M', 'T', 'W', 'T', 'F', 'S', 'S']; return <div className="weekly-chart"><div className="chart-y-labels"><span>100%</span><span>75%</span><span>50%</span><span>25%</span></div><div className="chart-area"><div className="chart-grid"><i /><i /><i /><i /></div><svg viewBox="0 0 500 140" preserveAspectRatio="none" aria-label="Weekly learning progress"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#8470ec" stopOpacity=".23" /><stop offset="1" stopColor="#8470ec" stopOpacity="0" /></linearGradient></defs><path d="M0,96 C25,90 35,65 83,70 S130,98 166,62 S215,42 250,57 S300,91 334,55 S385,30 417,42 S460,65 500,20 L500,140 L0,140Z" fill="url(#chartFill)" /><path d="M0,96 C25,90 35,65 83,70 S130,98 166,62 S215,42 250,57 S300,91 334,55 S385,30 417,42 S460,65 500,20" fill="none" stroke="#8470ec" strokeWidth="3" vectorEffect="non-scaling-stroke" strokeLinecap="round" /><path d="M0,112 C40,108 55,84 83,93 S135,116 166,93 S220,80 250,92 S304,110 334,88 S385,72 417,85 S465,97 500,70" fill="none" stroke="#d7d2ef" strokeWidth="2" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeDasharray="5 6" /></svg><div className="chart-x-labels">{days.map((day, i) => <span key={i}>{day}</span>)}</div></div></div> }

function SubjectsPage({ t, lang, onSubject }: { t: typeof text.ar; lang: Lang; onSubject: (id: string) => void }) { return <div className="subpage"><div className="page-heading"><div><div className="eyebrow-small">{lang === 'ar' ? 'مسار التعلّم · ٢٠٢٥/٢٠٢٦' : 'YOUR LEARNING PATH · 2025/26'}</div><h1>{t.subjects}</h1><p>{lang === 'ar' ? 'موادك، منظّمة على طريقتك.' : 'Your subjects, thoughtfully organized.'}</p></div><button className="outline-button"><GraduationCap size={16} />{lang === 'ar' ? 'الصف الثاني الثانوي' : 'Grade 11'}<ChevronDown size={15} /></button></div><div className="subjects-grid">{subjects.map((item, i) => <motion.button key={item.id} className={`subject-card ${item.tone}`} onClick={() => onSubject(item.id)} whileHover={{ y: -4 }}><div className="subject-card-top"><span className={`subject-icon ${item.tone}`}><item.icon size={21} /></span><span className="subject-counter">{String(i + 1).padStart(2, '0')}</span><MoreHorizontal size={19} /></div><h3>{item.name[lang]}</h3><p>{lang === 'ar' ? item.teacher : item.teacherEn}</p><div className="subject-card-progress"><span><b>{item.progress}%</b> {lang === 'ar' ? 'مكتمل' : 'complete'}</span><span>{item.done}/{item.chapters} {t.chapters}</span></div><div className="progress-track"><span style={{ width: `${item.progress}%` }} /></div><div className="next-lesson"><span>{lang === 'ar' ? 'الفصل التالي' : 'UP NEXT'}</span><b>{lang === 'ar' ? item.nextAr : item.next}</b><ChevronLeft size={16} /></div></motion.button>)}</div><div className="tip-banner"><span><Sparkles size={18} /></span><div><b>{lang === 'ar' ? 'كل إنجاز يبدأ بخطوة صغيرة' : 'Every milestone starts with a small step'}</b><p>{lang === 'ar' ? 'اختاري مادة وابدئي فصلًا جديدًا اليوم.' : 'Choose a subject and explore something new today.'}</p></div><button onClick={() => onSubject('biology')}>{t.study}<ArrowLeft size={15} /></button></div></div> }

function Achievements({ t, lang, completedQuizzes, visited, onSubject }: { t: typeof text.ar; lang: Lang; completedQuizzes: number; visited: number; onSubject: (id: string) => void }) { return <div className="subpage"><div className="page-heading"><div><div className="eyebrow-small">{lang === 'ar' ? 'كل خطوة تستحق الاحتفاء' : 'CELEBRATE EVERY STEP'}</div><h1>{t.achievements} <span className="heading-english">| My achievements</span></h1><p>{lang === 'ar' ? 'انظري كم تقدّمتِ، وكم أثرًا صنعتِ.' : 'Look how far you’ve come, and how much you’ve achieved.'}</p></div><button className="date-filter"><span>◷</span>{lang === 'ar' ? 'هذا الفصل الدراسي' : 'This term'}<ChevronDown size={15} /></button></div><div className="stats-row achievements-stats"><StatCard icon={<BookOpen size={17} />} tone="stat-purple" value={String(visited)} label={lang === 'ar' ? 'فصول تمت زيارتها' : 'Chapters visited'} detail="+3 this week" /><StatCard icon={<Target size={17} />} tone="stat-peach" value={String(completedQuizzes)} label={lang === 'ar' ? 'اختبارات مكتملة' : 'Quizzes completed'} detail={lang === 'ar' ? 'من أصل ٨' : 'of 8 assigned'} /><StatCard icon={<CheckCircle2 size={17} />} tone="stat-blue" value="86%" label={lang === 'ar' ? 'متوسط الإجابات الصحيحة' : 'Average accuracy'} detail="+6.2% this month" /><StatCard icon={<Clock3 size={17} />} tone="stat-mint" value="12.5" label={lang === 'ar' ? 'ساعة تعلّم' : 'Learning hours'} detail={lang === 'ar' ? 'هذا الشهر' : 'this month'} /></div><div className="achievement-layout"><section className="panel subject-achievements"><PanelHeading title={lang === 'ar' ? 'تقدّم المواد' : 'Subject progress'} action={lang === 'ar' ? 'عرض المواد' : 'View subjects'} onAction={() => onSubject('biology')} />{subjects.map((item) => <div className="achievement-subject" key={item.id}><span className={`subject-icon ${item.tone}`}><item.icon size={18} /></span><div><b>{item.name[lang]}</b><div className="progress-track"><span style={{ width: `${item.progress}%` }} /></div></div><strong>{item.progress}%</strong></div>)}</section><section className="panel badges-panel"><PanelHeading title={lang === 'ar' ? 'أوسمتك' : 'Your badges'} action={lang === 'ar' ? 'كل الإنجازات' : 'All badges'} /><div className="badge-grid"><Badge icon="✦" label={lang === 'ar' ? 'خطوة أولى' : 'First steps'} color="gold" /><Badge icon="🔥" label={lang === 'ar' ? '٧ أيام متتالية' : '7-day streak'} color="coral" /><Badge icon="◎" label={lang === 'ar' ? 'فصل مكتمل' : 'Chapter pro'} color="mint" /><Badge icon="♢" label={lang === 'ar' ? 'متعلّمة فضولية' : 'Curious mind'} color="purple" /><Badge icon="★" label={lang === 'ar' ? 'درجة كاملة' : 'Perfect score'} color="blue" /><Badge icon="✧" label={lang === 'ar' ? '١٠ ساعات تعلّم' : '10 hour club'} color="pink" /></div></section></div></div> }
function Badge({ icon, label, color }: { icon: string; label: string; color: string }) { return <div className={`badge ${color}`}><span>{icon}</span><b>{label}</b></div> }

function Tasks({ lang, onStart }: { lang: Lang; onStart: () => void }) { return <div className="subpage"><div className="page-heading"><div><div className="eyebrow-small">{lang === 'ar' ? 'جاهزة لتحدٍّ جديد؟' : 'READY FOR A NEW CHALLENGE?'}</div><h1>{text[lang].tasks}</h1><p>{lang === 'ar' ? 'كل سؤال فرصة لتكتشفي ما تعرفينه.' : 'Every question is a chance to discover what you know.'}</p></div><div className="task-count"><Target size={17} /><b>2</b><span>{lang === 'ar' ? 'مهام متاحة' : 'tasks available'}</span></div></div><div className="task-list"><TaskCard lang={lang} tone="mint" icon={<FlaskConical size={22} />} subject={subjects[0].name[lang]} title={lang === 'ar' ? 'اختبار الفصل الأول: الخلية' : 'Chapter 1 quiz: The cell'} description={lang === 'ar' ? 'اختبري فهمك لتراكيب الخلية ووظائفها.' : 'Test your understanding of cell structures and functions.'} onStart={onStart} /><TaskCard lang={lang} tone="lilac" icon={<BarChart3 size={22} />} subject={subjects[1].name[lang]} title={lang === 'ar' ? 'تدريب: المعادلات التربيعية' : 'Practice: Quadratic equations'} description={lang === 'ar' ? 'تدرّبي على حل المعادلات واكتشفي طرقًا جديدة.' : 'Practice solving equations and discover new approaches.'} onStart={onStart} /></div><div className="task-note"><Clock3 size={18} /><span><b>{lang === 'ar' ? 'خذي وقتك' : 'Take your time'}</b><small>{lang === 'ar' ? 'ستظهر لك نتيجتك مع شرح مفصّل بعد كل اختبار.' : 'You’ll see your score and a detailed explanation after each quiz.'}</small></span></div></div> }
function TaskCard({ lang, tone, icon, subject, title, description, onStart }: { lang: Lang; tone: string; icon: React.ReactNode; subject: string; title: string; description: string; onStart: () => void }) { return <div className="task-card"><span className={`task-icon ${tone}`}>{icon}</span><div className="task-body"><span className="task-subject">{subject} · {lang === 'ar' ? 'الفصل الأول' : 'Chapter 1'}</span><h3>{title}</h3><p>{description}</p><div className="task-meta"><span><CircleHelp size={14} />10 {lang === 'ar' ? 'أسئلة' : 'questions'}</span><span><Clock3 size={14} />10 {lang === 'ar' ? 'دقائق' : 'min'}</span><span><Award size={14} />100 XP</span></div></div><button className="primary-button" onClick={onStart}>{lang === 'ar' ? 'ابدئي الاختبار' : 'Start quiz'}<ArrowLeft size={15} className={lang === 'en' ? 'flip-icon' : ''} /></button></div> }

function Summary({ t, lang, subject, page, setPage, saved, setSaved, onBack, onStartQuiz }: { t: typeof text.ar; lang: Lang; subject: (typeof subjects)[number]; page: number; setPage: (page: number) => void; saved: boolean; setSaved: (saved: boolean) => void; onBack: () => void; onStartQuiz: () => void }) { return <div className="subpage content-page"><button className="back-link" onClick={onBack}><ArrowRight size={15} className={lang === 'en' ? 'flip-icon' : ''} />{t.back} {lang === 'ar' ? 'للمواد' : 'to subjects'}</button><div className="content-layout"><article className="summary-article"><div className="lesson-breadcrumb">{subject.name[lang]} <ChevronLeft size={13} /> {t.lessonLabel}</div><div className="lesson-title-row"><div><span className={`subject-icon ${subject.tone}`}><subject.icon size={19} /></span><h1>{t.chapterTitle}</h1><p>{lang === 'ar' ? 'ملخص تفاعلي · ٨ دقائق قراءة' : 'Interactive summary · 8 min read'}</p></div><button className={`icon-button bookmark-button ${saved ? 'saved' : ''}`} title={lang === 'ar' ? 'حفظ الملخص' : 'Save summary'} onClick={() => setSaved(!saved)}><Bookmark size={18} fill={saved ? 'currentColor' : 'none'} /></button></div><div className="summary-artwork"><div className="cell-diagram"><div className="cell-membrane"><div className="cell-nucleus" /><span className="cell-mito mito-one" /><span className="cell-mito mito-two" /><span className="cell-dot dot-one" /><span className="cell-dot dot-two" /><span className="cell-dot dot-three" /></div><span className="label-membrane">{lang === 'ar' ? 'الغشاء الخلوي' : 'Cell membrane'}<i /></span><span className="label-nucleus">{lang === 'ar' ? 'النواة' : 'Nucleus'}<i /></span><span className="label-cytoplasm">{lang === 'ar' ? 'السيتوبلازم' : 'Cytoplasm'}<i /></span></div><div className="diagram-caption"><span>{lang === 'ar' ? 'الشكل ١.١' : 'FIGURE 1.1'}</span>{lang === 'ar' ? 'تراكيب الخلية الحيوانية الأساسية' : 'Key structures of an animal cell'}</div></div><div className="summary-section"><span className="section-index">01</span><div><h2>{lang === 'ar' ? 'ما هي الخلية؟' : 'What is a cell?'}</h2><p>{t.summaryText}</p><p>{lang === 'ar' ? 'تحتوي معظم الخلايا على غشاء خلوي ينظم دخول المواد وخروجها، وسيتوبلازم تحدث فيه التفاعلات الحيوية، ونواة تتحكم في أنشطة الخلية.' : 'Most cells contain a cell membrane that regulates what enters and leaves, cytoplasm where essential reactions take place, and a nucleus that controls cell activities.'}</p></div></div><div className="key-point"><Sparkles size={17} /><p><b>{lang === 'ar' ? 'تذكّري:' : 'Remember:'}</b> {lang === 'ar' ? 'الخلية هي وحدة البناء الأساسية للكائنات الحية.' : 'The cell is the basic building block of living things.'}</p></div><div className="summary-pagination"><button onClick={() => setPage(Math.max(1, page - 1))} disabled={page === 1}><ChevronRight size={16} />{lang === 'ar' ? 'السابق' : 'Previous'}</button><span>{t.page} <b>{page}</b> {lang === 'ar' ? 'من ٤' : 'of 4'}<div className="page-dots"><i className="active" /><i /><i /><i /></div></span><button onClick={() => setPage(Math.min(4, page + 1))}>{lang === 'ar' ? 'التالي' : 'Next'}<ChevronLeft size={16} /></button></div></article><aside className="lesson-sidebar"><div className="lesson-progress-card"><span className="lesson-kicker">{lang === 'ar' ? 'رحلة الفصل' : 'CHAPTER JOURNEY'}</span><div className="lesson-ring"><div><b>{page * 25}%</b><small>{lang === 'ar' ? 'مكتمل' : 'complete'}</small></div></div><p>{lang === 'ar' ? 'أنتِ تحرزين تقدمًا رائعًا!' : 'You’re making great progress!'}</p></div><div className="lesson-toc"><h3>{lang === 'ar' ? 'في هذا الملخص' : 'In this summary'}</h3>{[lang === 'ar' ? 'ما هي الخلية؟' : 'What is a cell?', lang === 'ar' ? 'تراكيب الخلية' : 'Cell structures', lang === 'ar' ? 'الخلايا النباتية والحيوانية' : 'Plant & animal cells', lang === 'ar' ? 'تحققي من فهمك' : 'Check your knowledge'].map((section, i) => <button className={i === 0 ? 'toc-current' : ''} key={i} onClick={() => setPage(Math.min(i + 1, 4))}><span>{String(i + 1).padStart(2, '0')}</span>{section}</button>)}</div><div className="lesson-quiz-card"><span className="quiz-round-icon"><Target size={19} /></span><h3>{lang === 'ar' ? 'تأكدي من فهمك' : 'Check your understanding'}</h3><p>{lang === 'ar' ? 'اختبار قصير من ١٠ أسئلة على هذا الفصل.' : 'A quick 10-question quiz on this chapter.'}</p><button onClick={onStartQuiz}>{t.takeQuiz}<ArrowLeft size={15} className={lang === 'en' ? 'flip-icon' : ''} /></button></div></aside></div><div className="content-protection"><ShieldCheck size={14} />{t.protection}</div></div> }

function Quiz({ t, lang, seconds, formatTime, index, setIndex, answers, setAnswers, onSubmit, onBack }: { t: typeof text.ar; lang: Lang; seconds: number; formatTime: (time: number) => string; index: number; setIndex: (i: number) => void; answers: number[]; setAnswers: (answers: number[]) => void; onSubmit: () => void; onBack: () => void }) {
  const q = quizQuestions[index]
  return <div className="quiz-page">
    <div className="quiz-top">
      <button className="back-link" onClick={onBack}><ArrowRight size={15} className={lang === 'en' ? 'flip-icon' : ''} />{lang === 'ar' ? 'العودة للفصل' : 'Back to chapter'}</button>
      <div className="quiz-subject-pill"><FlaskConical size={15} />{subjects[0].name[lang]} <span>·</span> {lang === 'ar' ? 'الفصل الأول' : 'Chapter 1'}</div>
      <div className={`timer-pill ${seconds < 60 ? 'timer-low' : ''}`}><Clock3 size={16} /><b>{formatTime(seconds)}</b><small>{lang === 'ar' ? 'متبقي' : 'remaining'}</small></div>
    </div>
    <div className="quiz-progress-track"><span style={{ width: `${((index + 1) / 10) * 100}%` }} /></div>
    <div className="quiz-layout">
      <section className="quiz-main">
        <div className="quiz-kicker"><span>{lang === 'ar' ? 'اختبار الفصل' : 'CHAPTER QUIZ'}</span><span>{String(index + 1).padStart(2, '0')} <i>/</i> 10</span></div>
        <h1>{q.q}</h1><h2 dir="rtl">{q.ar}</h2>
        <div className="answer-options">{q.options.map((option, i) => <button key={option} className={`answer-option ${answers[index] === i ? 'answer-selected' : ''}`} onClick={() => { const next = [...answers]; next[index] = i; setAnswers(next) }}><span className="option-letter">{String.fromCharCode(65 + i)}</span><span className="option-copy"><b>{lang === 'ar' ? q.optionsAr[i] : option}</b><small>{lang === 'ar' ? option : q.optionsAr[i]}</small></span><span className="option-radio">{answers[index] === i && <i />}</span></button>)}</div>
        <div className="quiz-navigation"><button className="outline-button" disabled={index === 0} onClick={() => setIndex(index - 1)}><ChevronRight size={16} />{t.previous}</button><span>{answers.filter((value) => value !== -1).length} / 10 {lang === 'ar' ? 'أُجيب عنها' : 'answered'}</span>{index < 9 ? <button className="primary-button" onClick={() => setIndex(index + 1)}>{t.next}<ChevronLeft size={16} /></button> : <button className="primary-button" onClick={onSubmit}>{t.submit}<Check size={16} /></button>}</div>
      </section>
      <aside className="quiz-rail">
        <div className="rail-card"><h3>{lang === 'ar' ? 'الأسئلة' : 'Questions'}</h3><div className="question-grid">{quizQuestions.map((_, i) => <button key={i} className={`${index === i ? 'q-current' : ''} ${answers[i] !== -1 ? 'q-answered' : ''}`} onClick={() => setIndex(i)}>{i + 1}</button>)}</div><div className="rail-legend"><span><i className="legend-current" />{lang === 'ar' ? 'الحالي' : 'Current'}</span><span><i className="legend-done" />{lang === 'ar' ? 'تمت الإجابة' : 'Answered'}</span></div></div>
        <div className="quiz-tip"><Sparkles size={17} /><b>{lang === 'ar' ? 'خذي نفسًا عميقًا' : 'You’ve got this!'}</b><p>{lang === 'ar' ? 'اقرئي السؤال جيدًا، وخذي وقتك في التفكير.' : 'Read each question carefully and take your time.'}</p></div>
      </aside>
    </div>
  </div>
}

function Results({ t, lang, answers, score, onBack, onRetry }: { t: typeof text.ar; lang: Lang; answers: number[]; score: number; onBack: () => void; onRetry: () => void }) { return <div className="results-page"><div className="results-hero"><span className="result-confetti">✦</span><span className="result-award"><Trophy size={27} /></span><div className="eyebrow-small">{lang === 'ar' ? 'أحسنتِ! خطوة أخرى نحو التميّز' : 'WELL DONE · ANOTHER STEP FORWARD'}</div><h1>{t.results}</h1><p>{lang === 'ar' ? 'كل محاولة تقرّبك من هدفك. استمرّي!' : 'Every attempt brings you closer to your goal. Keep going!'}</p><div className="score-circle"><div><b>{score * 10}<small>%</small></b><span>{score} / 10 {lang === 'ar' ? 'صحيحة' : 'correct'}</span></div></div><div className="result-metrics"><span><CheckCircle2 size={16} /><b>{score}</b>{t.correct}</span><span><X size={16} /><b>{10 - score}</b>{t.incorrect}</span><span><Clock3 size={16} /><b>08:24</b>{lang === 'ar' ? 'الوقت المستغرق' : 'time spent'}</span></div></div><div className="results-details"><div className="results-heading"><div><h2>{lang === 'ar' ? 'مراجعة الإجابات' : 'Answer review'}</h2><p>{lang === 'ar' ? 'تعلّمي من كل إجابة، صحيحة كانت أم خاطئة.' : 'Learn from every answer, right or wrong.'}</p></div><span className="saved-badge"><CheckCircle2 size={14} />{t.resultsSaved}</span></div>{quizQuestions.map((item, i) => { const right = answers[i] === item.answer; return <div className="answer-review" key={i}><div className={`review-status ${right ? 'review-correct' : 'review-wrong'}`}>{right ? <Check size={15} /> : <X size={15} />}</div><div className="review-content"><b>{i + 1}. {lang === 'ar' ? item.ar : item.q}</b><p>{lang === 'ar' ? 'إجابتك:' : 'Your answer:'} <strong className={right ? 'text-green' : 'text-red'}>{answers[i] === -1 ? (lang === 'ar' ? 'لم تتم الإجابة' : 'Not answered') : lang === 'ar' ? item.optionsAr[answers[i]] : item.options[answers[i]]}</strong>{!right && <span> · {lang === 'ar' ? 'الصحيح:' : 'Correct:'} <strong className="text-green">{lang === 'ar' ? item.optionsAr[item.answer] : item.options[item.answer]}</strong></span>}</p><small><Sparkles size={13} /><b>{t.explanation}:</b> {lang === 'ar' ? item.whyAr : item.why}</small></div></div> })}<div className="results-actions"><button className="outline-button" onClick={onBack}>{t.back} {lang === 'ar' ? 'للفصول' : 'to chapters'}</button><button className="primary-button" onClick={onRetry}>{lang === 'ar' ? 'إعادة الاختبار' : 'Try again'}<ArrowLeft size={15} className={lang === 'en' ? 'flip-icon' : ''} /></button></div></div></div> }

function Payments({ t, lang, onUpgrade }: { t: typeof text.ar; lang: Lang; onUpgrade: () => void }) { return <div className="subpage"><div className="page-heading"><div><div className="eyebrow-small">{lang === 'ar' ? 'مساحتك التعليمية، بلا حدود' : 'YOUR LEARNING SPACE · UNLIMITED'}</div><h1>{t.payments}</h1><p>{lang === 'ar' ? 'كل ما تحتاجينه لتنمية أثر معرفتك.' : 'Everything you need to grow your impact.'}</p></div></div><div className="subscription-grid"><div className="subscription-card current-plan"><span className="active-plan-pill"><CheckCircle2 size={14} />{t.activePlan}</span><div className="plan-icon"><Sparkles size={21} /></div><h2>{lang === 'ar' ? 'أثَر · الفصل الدراسي' : 'ATHAR · Full term'}</h2><p>{lang === 'ar' ? 'اشتراكك يمنحك وصولًا كاملًا إلى رحلتك التعليمية.' : 'Your subscription gives you full access to your learning journey.'}</p><div className="plan-price"><b>{lang === 'ar' ? '٩٩٠' : '990'} <small>{lang === 'ar' ? 'ج.م' : 'EGP'}</small></b><span> / {lang === 'ar' ? 'فصل دراسي' : 'term'}</span></div><div className="plan-features"><span><CheckCircle2 size={15} />{lang === 'ar' ? 'كل المواد والملخصات' : 'All subjects and summaries'}</span><span><CheckCircle2 size={15} />{lang === 'ar' ? 'اختبارات تفاعلية غير محدودة' : 'Unlimited interactive quizzes'}</span><span><CheckCircle2 size={15} />{lang === 'ar' ? 'متابعة التقدّم والإنجازات' : 'Progress and achievement tracking'}</span><span><CheckCircle2 size={15} />{lang === 'ar' ? 'دعم تعليمي على مدار الساعة' : 'Dedicated learning support'}</span></div><button className="primary-button full-button" onClick={onUpgrade}>{lang === 'ar' ? 'إدارة الاشتراك' : 'Manage subscription'}<ArrowLeft size={16} /></button></div><div className="payment-history panel"><PanelHeading title={lang === 'ar' ? 'سجل المدفوعات' : 'Payment history'} /><div className="payment-row"><span className="payment-icon"><CreditCard size={18} /></span><span><b>{lang === 'ar' ? 'اشتراك الفصل الدراسي' : 'Full term subscription'}</b><small>Visa •••• 2841 · {lang === 'ar' ? '١ سبتمبر ٢٠٢٥' : 'Sep 1, 2025'}</small></span><span className="payment-amount">990 EGP<small><CheckCircle2 size={12} />{lang === 'ar' ? 'تم الدفع' : 'Paid'}</small></span></div><div className="payment-method"><span><ShieldCheck size={18} /></span><div><b>{lang === 'ar' ? 'بوابات دفع آمنة' : 'Secure payment gateway'}</b><small>{lang === 'ar' ? 'Visa · بطاقات بنكية · Vodafone Cash' : 'Visa · Debit cards · Vodafone Cash'}</small></div><span className="secure-label">{lang === 'ar' ? 'مشفّر' : 'Encrypted'}</span></div></div></div></div> }

function Progress({ t, lang, role }: { t: typeof text.ar; lang: Lang; role: Role }) { return <div className="subpage"><div className="page-heading"><div><div className="eyebrow-small">{lang === 'ar' ? 'نظرة كاملة على التعلّم' : 'A CLOSER LOOK AT LEARNING'}</div><h1>{role === 'parent' ? t.childProgress : t.progress}</h1><p>{lang === 'ar' ? 'تقدّمٌ حقيقي، خطوةً بعد خطوة.' : 'Real progress, one step at a time.'}</p></div><button className="outline-button"><span className="profile-avatar small-avatar">م</span>{lang === 'ar' ? 'مريم أحمد' : 'Mariam Ahmed'}<ChevronDown size={15} /></button></div><div className="stats-row"><StatCard icon={<BookOpen size={17} />} tone="stat-purple" value="25" label={lang === 'ar' ? 'فصلًا مكتملًا' : 'Chapters completed'} detail="+4 this week" /><StatCard icon={<Target size={17} />} tone="stat-peach" value="86%" label={lang === 'ar' ? 'متوسط الاختبارات' : 'Quiz average'} detail="+6.2% this month" /><StatCard icon={<Clock3 size={17} />} tone="stat-blue" value="12.5" label={lang === 'ar' ? 'ساعة تعلّم' : 'Learning hours'} detail={lang === 'ar' ? 'هذا الشهر' : 'this month'} /><StatCard icon={<Zap size={17} />} tone="stat-mint" value="7" label={t.streak} detail="Personal best!" /></div><div className="panel progress-table"><PanelHeading title={lang === 'ar' ? 'التقدّم حسب المادة' : 'Progress by subject'} action={lang === 'ar' ? 'تصدير التقرير' : 'Export report'} /><div className="progress-table-head"><span>{lang === 'ar' ? 'المادة الدراسية' : 'SUBJECT'}</span><span>{lang === 'ar' ? 'الفصول المكتملة' : 'CHAPTERS'}</span><span>{lang === 'ar' ? 'معدل الاختبارات' : 'QUIZ AVG.'}</span><span>{lang === 'ar' ? 'التقدّم' : 'PROGRESS'}</span></div>{subjects.map((item, index) => <div className="progress-table-row" key={item.id}><span className="table-subject"><span className={`subject-icon ${item.tone}`}><item.icon size={17} /></span><b>{item.name[lang]}</b></span><span>{item.done} / {item.chapters}</span><span>{[88, 76, 94, 82][index]}%</span><span className="table-progress"><span className="progress-track"><i style={{ width: `${item.progress}%` }} /></span><b>{item.progress}%</b></span></div>)}</div><div className="parent-insight"><span><Sparkles size={19} /></span><div><b>{lang === 'ar' ? 'تقدّم جميل هذا الأسبوع!' : 'Wonderful progress this week!'}</b><p>{lang === 'ar' ? 'مريم أكملت ٤ فصول وأجابت عن ٣ اختبارات. استمروا في تشجيعها!' : 'Mariam completed 4 chapters and took 3 quizzes. Keep cheering her on!'}</p></div></div></div> }

function AdminContent({ t, lang, onToast }: { t: typeof text.ar; lang: Lang; onToast: (message: string) => void }) { const [tab, setTab] = useState('chapters'); const [chapter, setChapter] = useState(''); return <div className="subpage"><div className="page-heading"><div><div className="eyebrow-small">{lang === 'ar' ? 'مركز إدارة المحتوى' : 'CONTENT MANAGEMENT CENTER'}</div><h1>{t.content}</h1><p>{lang === 'ar' ? 'أنشئ محتوى يترك أثرًا في كل درس.' : 'Create content that leaves an impact in every lesson.'}</p></div><button className="primary-button" onClick={() => onToast(lang === 'ar' ? 'أضيفي عنوان الفصل أولًا لبدء الإنشاء' : 'Add a chapter title to begin')}><Plus size={16} />{lang === 'ar' ? 'إضافة محتوى' : 'Add content'}</button></div><div className="admin-tabs">{[['chapters', lang === 'ar' ? 'الفصول' : 'Chapters'], ['summaries', lang === 'ar' ? 'الملخصات' : 'Summaries'], ['quizzes', lang === 'ar' ? 'الاختبارات' : 'Quizzes']].map(([key, label]) => <button className={tab === key ? 'tab-active' : ''} onClick={() => setTab(key)} key={key}>{label}</button>)}</div><div className="panel admin-content-panel"><div className="admin-tools"><div className="input-wrap"><Search size={16} /><input placeholder={lang === 'ar' ? 'ابحث في المحتوى...' : 'Search content...'} /></div><button className="outline-button">{lang === 'ar' ? 'كل المواد' : 'All subjects'}<ChevronDown size={14} /></button></div>{subjects.map((item, i) => <div className="admin-row" key={item.id}><span className={`subject-icon ${item.tone}`}><item.icon size={17} /></span><span className="admin-row-copy"><b>{item.lessons[i % item.lessons.length]}</b><small>{item.name[lang]} · {lang === 'ar' ? `الفصل ${i + 1}` : `Chapter ${i + 1}`}</small></span><span className="published-pill"><i />{lang === 'ar' ? 'منشور' : 'Published'}</span><button onClick={() => onToast(lang === 'ar' ? 'خيارات إدارة المحتوى' : 'Content management options')}><MoreHorizontal size={18} /></button></div>)}</div><div className="upload-zone"><span><Plus size={19} /></span><b>{lang === 'ar' ? 'أضيفي فصلًا دراسيًا جديدًا' : 'Add a new chapter'}</b><p>{lang === 'ar' ? 'أضيفي ملخصات نصية وصورًا واختبارات تفاعلية.' : 'Add text summaries, images, and interactive quizzes.'}</p><div className="admin-input"><input placeholder={lang === 'ar' ? 'عنوان الفصل الجديد...' : 'New chapter title...'} value={chapter} onChange={(e) => setChapter(e.target.value)} /><button className="primary-button" onClick={() => { if (!chapter.trim()) onToast(lang === 'ar' ? 'اكتبي عنوان الفصل أولًا' : 'Please enter a chapter title first'); else { onToast(lang === 'ar' ? `تمت إضافة "${chapter}" كمسودة` : `"${chapter}" added as a draft`); setChapter('') } }}><Plus size={15} />{lang === 'ar' ? 'إنشاء مسودة' : 'Create draft'}</button></div></div></div> }

function AdminUsers({ t, lang, onToast }: { t: typeof text.ar; lang: Lang; onToast: (message: string) => void }) { return <div className="subpage"><div className="page-heading"><div><div className="eyebrow-small">{lang === 'ar' ? 'مجتمع أثَر' : 'THE ATHAR COMMUNITY'}</div><h1>{t.users}</h1><p>{lang === 'ar' ? 'إدارة الطلاب وأولياء الأمور بأمان.' : 'Manage student and parent accounts securely.'}</p></div><button className="primary-button" onClick={() => onToast(lang === 'ar' ? 'سيتم ربط إضافة المستخدمين بالخادم' : 'User creation will be connected to the backend')}><Plus size={16} />{lang === 'ar' ? 'إضافة مستخدم' : 'Add user'}</button></div><div className="stats-row"><StatCard icon={<Users size={17} />} tone="stat-purple" value="1,284" label={lang === 'ar' ? 'إجمالي الطلاب' : 'Total students'} detail="+12% this month" /><StatCard icon={<UserRound size={17} />} tone="stat-blue" value="862" label={lang === 'ar' ? 'أولياء الأمور' : 'Parents'} detail="98% linked" /><StatCard icon={<CreditCard size={17} />} tone="stat-mint" value="1,142" label={lang === 'ar' ? 'اشتراكات نشطة' : 'Active subscriptions'} detail="89% of students" /><StatCard icon={<ArrowUpRight size={17} />} tone="stat-peach" value="94%" label={lang === 'ar' ? 'نسبة الاحتفاظ' : 'Retention rate'} detail="+2.4%" /></div><div className="panel progress-table"><PanelHeading title={lang === 'ar' ? 'أحدث الحسابات' : 'Recent accounts'} action={lang === 'ar' ? 'عرض جميع الحسابات' : 'View all accounts'} onAction={() => onToast(lang === 'ar' ? 'جميع الحسابات محدثة' : 'All accounts are up to date')} /><div className="progress-table-head users-head"><span>{lang === 'ar' ? 'الاسم' : 'NAME'}</span><span>{lang === 'ar' ? 'نوع الحساب' : 'ACCOUNT TYPE'}</span><span>{lang === 'ar' ? 'الصف الدراسي' : 'GRADE'}</span><span>{lang === 'ar' ? 'الحالة' : 'STATUS'}</span></div>{[['Mariam Ahmed', 'Student', 'Grade 11', 'Active'], ['Youssef Khaled', 'Student', 'Grade 10', 'Active'], ['Ahmed Mohamed', 'Parent', '—', 'Active'], ['Nour Hassan', 'Student', 'Grade 9', 'Pending']].map((row, i) => <div className="progress-table-row users-row" key={row[0]}><span className="table-subject"><span className={`profile-avatar user-avatar-${i}`}>{row[0][0]}</span><b>{row[0]}</b></span><span>{lang === 'ar' ? (row[1] === 'Parent' ? 'ولي أمر' : 'طالب') : row[1]}</span><span>{row[2]}</span><span><i className={`user-status ${row[3] === 'Active' ? 'status-active' : 'status-pending'}`} />{lang === 'ar' ? (row[3] === 'Active' ? 'نشط' : 'بانتظار التفعيل') : row[3]}</span></div>)}</div></div> }

function Notice({ icon, title, body, time }: { icon: React.ReactNode; title: string; body: string; time: string }) { return <div className="notice-row"><span>{icon}</span><div><b>{title}</b><p>{body}</p><small>{time}</small></div><i /></div> }
function Toast({ message }: { message: string }) { return <AnimatePresence>{message && <motion.div className="toast-message" initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 12 }}><CheckCircle2 size={17} />{message}</motion.div>}</AnimatePresence> }

function Onboarding({ active, setActive, lang, t, system, setSystem, grade, setGrade, finishPayment, onDone }: { active: 'system' | 'grade' | 'payment' | 'success' | null; setActive: (step: 'system' | 'grade' | 'payment' | 'success' | null) => void; lang: Lang; t: typeof text.ar; system: string; setSystem: (system: string) => void; grade: string; setGrade: (grade: string) => void; finishPayment: () => void; onDone: () => void }) {
  const [method, setMethod] = useState('card')
  const [cardNumber, setCardNumber] = useState('')
  const [phone, setPhone] = useState('')
  if (!active) return null
  const grades = ['Grade 7', 'Grade 8', 'Grade 9', 'Grade 10', 'Grade 11', 'Grade 12']
  return <div className="modal-backdrop"><motion.div className="onboarding-modal" initial={{ opacity: 0, y: 16, scale: .98 }} animate={{ opacity: 1, y: 0, scale: 1 }}><button className="modal-close" onClick={() => setActive(null)} aria-label="Close"><X size={19} /></button>{active !== 'success' && <div className="onboarding-stepper"><span className={['system', 'grade'].includes(active) ? 'step-done' : ''}>1</span><i /><span className={active === 'grade' || active === 'payment' ? 'step-done' : ''}>2</span><i /><span className={active === 'payment' ? 'step-current' : ''}>3</span></div>}
    {active === 'system' && <><div className="modal-icon"><GraduationCap size={23} /></div><h2>{t.chooseSystem}</h2><p className="modal-sub">{lang === 'ar' ? 'سنخصص تجربتك لتناسب مدرستك.' : 'We’ll tailor your learning experience to your school.'}</p><div className="choice-cards"><button className={`choice-card ${system.includes('Arabic') ? 'choice-selected' : ''}`} onClick={() => setSystem('Arabic schools')}><span className="choice-flag">ع</span><span><b>{t.arabicSchool}</b><small>{lang === 'ar' ? 'مناهج عربية بالكامل' : 'Full Arabic curriculum'}</small></span>{system.includes('Arabic') && <CheckCircle2 size={18} />}</button><button className={`choice-card ${system.includes('Language') ? 'choice-selected' : ''}`} onClick={() => setSystem('Language schools')}><span className="choice-flag choice-english">EN</span><span><b>{t.englishSchool}</b><small>{lang === 'ar' ? 'مناهج باللغة الإنجليزية' : 'English-language curriculum'}</small></span>{system.includes('Language') && <CheckCircle2 size={18} />}</button></div><button className="primary-button full-button" onClick={() => setActive('grade')}>{lang === 'ar' ? 'متابعة' : 'Continue'}<ArrowLeft size={16} /></button></>}
    {active === 'grade' && <><div className="modal-icon"><BookOpen size={22} /></div><h2>{t.chooseGrade}</h2><p className="modal-sub">{lang === 'ar' ? 'اختاري صفك الدراسي لعرض المحتوى المناسب.' : 'Choose your grade to see the right learning content.'}</p><span className="grade-group-label">{t.prep}</span><div className="grade-options">{grades.slice(0, 3).map((item) => <button className={grade === item ? 'grade-selected' : ''} key={item} onClick={() => setGrade(item)}>{item.replace('Grade', lang === 'ar' ? 'الصف' : 'Grade')} {grade === item && <Check size={14} />}</button>)}</div><span className="grade-group-label">{t.secondary}</span><div className="grade-options">{grades.slice(3).map((item) => <button className={grade === item ? 'grade-selected' : ''} key={item} onClick={() => setGrade(item)}>{item.replace('Grade', lang === 'ar' ? 'الصف' : 'Grade')} {grade === item && <Check size={14} />}</button>)}</div><button className="primary-button full-button" onClick={() => setActive('payment')}>{lang === 'ar' ? 'المتابعة للاشتراك' : 'Continue to subscription'}<ArrowLeft size={16} /></button></>}
    {active === 'payment' && <><div className="modal-icon"><WalletCards size={22} /></div><h2>{t.choosePlan}</h2><p className="modal-sub">{lang === 'ar' ? 'اشتراك فصل دراسي كامل لتبدئي رحلتك.' : 'A full term of learning, all in one place.'}</p><div className="payment-summary"><span><span>{t.monthly}</span><b>990 {lang === 'ar' ? 'ج.م' : 'EGP'}</b></span><small>{t.term} · {lang === 'ar' ? 'يشمل كل المواد والملخصات والاختبارات' : 'Includes all subjects, summaries & quizzes'}</small></div><div className="payment-methods"><button className={method === 'card' ? 'method-selected' : ''} onClick={() => setMethod('card')}><CreditCard size={19} /><span><b>{lang === 'ar' ? 'بطاقة بنكية' : 'Bank card'}</b><small>Visa · Mastercard</small></span>{method === 'card' && <CheckCircle2 size={17} />}</button><button className={method === 'vodafone' ? 'method-selected' : ''} onClick={() => setMethod('vodafone')}><span className="vodafone-mark">V</span><span><b>Vodafone Cash</b><small>{lang === 'ar' ? 'دفع آمن عبر المحفظة' : 'Secure wallet payment'}</small></span>{method === 'vodafone' && <CheckCircle2 size={17} />}</button></div>{method === 'card' ? <label className="field-label">{lang === 'ar' ? 'رقم البطاقة' : 'Card number'}<div className="input-wrap"><CreditCard size={16} /><input value={cardNumber} onChange={(e) => setCardNumber(e.target.value)} placeholder="••••  ••••  ••••  ••••" maxLength={19} /></div></label> : <label className="field-label">{lang === 'ar' ? 'رقم محفظة فودافون' : 'Vodafone Cash number'}<div className="input-wrap"><MessageCircle size={16} /><input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="01X XXXX XXXX" /></div></label>}<div className="payment-security"><ShieldCheck size={14} />{lang === 'ar' ? 'لا نحتفظ ببيانات بطاقتك. الدفع الآمن قيد الإعداد.' : 'Card details aren’t stored. Secure gateway setup is pending.'}</div><button className="primary-button full-button" onClick={finishPayment}>{t.payNow}<LockKeyhole size={15} /></button><small className="payment-demo-note">{t.paymentNotice}</small></>}
    {active === 'success' && <div className="payment-success"><span className="success-icon"><CheckCircle2 size={34} /></span><span className="eyebrow-small">{lang === 'ar' ? 'أهلًا بك في أثَر' : 'WELCOME TO ATHAR'}</span><h2>{t.paymentDone}</h2><p>{t.paymentSub}</p><div className="success-plan"><span className="profile-avatar small-avatar"><Sparkles size={17} /></span><span><b>{t.monthly}</b><small>{grade} · {system}</small></span><CheckCircle2 size={17} /></div><button className="primary-button full-button" onClick={onDone}>{t.startLearning}<ArrowLeft size={16} /></button><p className="success-note"><ShieldCheck size={14} />{lang === 'ar' ? 'تم تفعيل وصولك التعليمي فورًا' : 'Your learning access is now active'}</p></div>}
  </motion.div></div>
}

export default App
